head.script:
scwin.trigger1_onclick = function(e) {
	var scId = "";
	var options = {
		common: {
			fileName: "dataList.xlsx",
			multipleSheet: "true",
			showProcess: false
		},
		excelInfo: [{
				dataListId: "dataList1",
				sheetName: "첫번째 sheet",
				removeColumns: "",
				wframeId: scId
			},
			{
				dataListId: "dataList2",
				sheetName: "두번째 sheet",
				removeColumns: "",
				wframeId: scId
			},
			{
				dataListId: "dataList9",
				sheetName: "세번째 sheet",
				removeColumns: "",
				wframeId: scId
			}
		]
	};
	WebSquare.util.multipleDataListDownload(options);
};
scwin.trigger13_onclick = function(e) {
	if ($p.data.get("json", ["dataList9"])) {
		$p.data.remove("dataList9");
	}
	var option = {
		"id": "dataList9",
		"type": "dataList",
		"option": {
			"baseNode": "list",
			"repeatNode": "map"
		},
		"columnInfo": [{
			"id": "Code",
			"name": "코드그룹",
			"dataType": "text"
		}, {
			"id": "CodeName",
			"name": "코드명",
			"dataType": "text"
		}]
	};
	$p.data.create(option);
};
scwin.getErrorLog = function() {
	return WebSquare.logger.getErrorLog();
};
